/* Device-local workspace preferences. Panels keep their live controls when moved. */
'use strict';
globalThis.SplitPanels=(()=>{
 const key='split-workspace-v1',defaults={assets:'left',formats:'left',campaign:'left',layers:'right',properties:'right',background:'right'};
 const panelList=Object.keys(defaults),panels=new Map(panelList.map(id=>[id,$(`panel-${id}`)]));
 let state={widths:{left:260,right:260},panels:{}},interaction=null,z=20;
 const screen=()=>({w:window.innerWidth||1280,h:window.innerHeight||800});
 const limit=(v,a,b)=>Math.max(a,Math.min(b,v));
 function prefs(id){if(!state.panels[id])state.panels[id]={dock:defaults[id],order:panelList.indexOf(id),width:300,height:0,x:40,y:90,collapsed:['campaign','background'].includes(id)};return state.panels[id];}
 function read(){try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved&&typeof saved==='object'){for(const side of ['left','right'])if(Number.isFinite(saved.widths?.[side]))state.widths[side]=limit(saved.widths[side],210,420);for(const id of panelList){const p=saved.panels?.[id];if(!p||!['left','right','float'].includes(p.dock))continue;const d=prefs(id);d.dock=p.dock;d.collapsed=!!p.collapsed;for(const name of ['order','width','height','x','y'])if(Number.isFinite(p[name]))d[name]=p[name];d.width=limit(d.width,210,4096);d.height=limit(d.height,0,8192);}}}catch{}}
 function save(){try{localStorage.setItem(key,JSON.stringify(state));}catch{}}
 function contain(id){const p=prefs(id),s=screen();p.width=limit(p.width,Math.min(210,s.w-16),Math.max(210,s.w-16));p.x=limit(p.x,8,Math.max(8,s.w-p.width-8));const bar=$('generationBar').getBoundingClientRect(),top=Math.max(8,(bar.bottom??bar.top+bar.height)+8);p.y=limit(p.y,top,Math.max(top,s.h-80));if(p.height)p.height=limit(p.height,80,Math.max(80,s.h-80));}
 function appearance(id){const panel=panels.get(id),p=prefs(id);panel.classList.toggle('floating',p.dock==='float');panel.classList.toggle('collapsed',p.collapsed);panel.querySelector('.panel-collapse').textContent=p.collapsed?'+':'−';panel.querySelector('.panel-collapse').setAttribute('aria-expanded',String(!p.collapsed));panel.querySelector('.panel-collapse').setAttribute('aria-label',`${p.collapsed?'Expandir':'Recolher'} painel ${panel.querySelector('.panel-grip').textContent.replace('⠿','').trim()}`);panel.querySelector('.panel-body').hidden=p.collapsed;panel.querySelector('.panel-resize').hidden=p.collapsed;panel.style.maxHeight=p.dock==='float'?`${Math.max(80,screen().h-p.y-8)}px`:'';panel.style.width=p.dock==='float'?`${p.width}px`:'';panel.style.left=p.dock==='float'?`${p.x}px`:'';panel.style.top=p.dock==='float'?`${p.y}px`:'';panel.style.height=p.collapsed?'':p.height?`${p.height}px`:'';}
 function widths(){document.querySelector('.app').style.setProperty('--left-panel-width',`${state.widths.left}px`);document.querySelector('.app').style.setProperty('--right-panel-width',`${state.widths.right}px`);}
 function render(){widths();for(const side of ['left','right','float'])for(const id of panelList.filter(id=>prefs(id).dock===side).sort((a,b)=>prefs(a).order-prefs(b).order)){if(side==='float')contain(id);(side==='float'?$('floatingPanels'):$(side==='left'?'leftDock':'rightDock')).append(panels.get(id));appearance(id);}requestAnimationFrame(()=>{if(current()&&!$('editor').hidden)sizeStage();});}
 function reorder(){for(const side of ['left','right']){const children=Array.from($(side==='left'?'leftDock':'rightDock').children);children.forEach((panel,i)=>{const id=panel.dataset.panel;if(panels.has(id))prefs(id).order=i;});}}
 function move(id,dock,before=null){const panel=panels.get(id),p=prefs(id);p.dock=dock;if(dock==='float'){contain(id);panel.style.zIndex=++z;$('floatingPanels').append(panel);}else{const holder=$(dock==='left'?'leftDock':'rightDock');before&&before!==panel?holder.insertBefore(panel,before):holder.append(panel);reorder();}appearance(id);save();requestAnimationFrame(()=>{if(current()&&!$('editor').hidden)sizeStage();});}
 function start(id,type,ev){if(ev.button!==0||interaction||drag||pan)return;ev.preventDefault();const panel=panels.get(id),r=panel.getBoundingClientRect(),p=prefs(id);interaction={id,type,pointerId:ev.pointerId,startX:ev.clientX,startY:ev.clientY,x:r.left,y:r.top,width:r.width,height:r.height,dock:p.dock,changed:false,handle:ev.currentTarget};ev.currentTarget.setPointerCapture(ev.pointerId);panel.style.zIndex=++z;}
 function dockAt(x,y,previous=null){
  const candidates=[];
  for(const side of ['left','right']){
   const holder=$(side==='left'?'leftDock':'rightDock'),r=holder.getBoundingClientRect();
   if(!r.width||!r.height)continue;
   const threshold=side===previous?42:28,right=r.left+r.width,bottom=r.top+r.height;
   const dx=Math.max(r.left-x,0,x-right),dy=Math.max(r.top-y,0,y-bottom);
   if(dx<=threshold&&dy<=threshold)candidates.push({side,distance:Math.hypot(dx,dy)});
  }
  return candidates.sort((a,b)=>a.distance-b.distance)[0]?.side||null;
 }
 function target(i,x,y){i.clientX=x;i.clientY=y;i.drop=dockAt(x,y,i.drop);i.before=null;if(i.drop){const holder=$(i.drop==='left'?'leftDock':'rightDock');i.before=Array.from(holder.children).find(panel=>panel!==panels.get(i.id)&&y<panel.getBoundingClientRect().top+panel.getBoundingClientRect().height/2)||null;}for(const side of ['left','right'])$(side==='left'?'leftDock':'rightDock').classList.toggle('dock-target',i.drop===side);}
 function pointerMove(ev){const i=interaction;if(!i||i.pointerId!==ev.pointerId)return;const dx=ev.clientX-i.startX,dy=ev.clientY-i.startY;if(!i.changed&&Math.hypot(dx,dy)<5)return;i.changed=true;const p=prefs(i.id),panel=panels.get(i.id);if(i.type==='move'){if(p.dock!=='float'){p.x=i.x;p.y=i.y;p.width=i.width;move(i.id,'float');i.handle.setPointerCapture(ev.pointerId);}p.x=i.x+dx;p.y=i.y+dy;contain(i.id);appearance(i.id);target(i,ev.clientX,ev.clientY);}else{if(p.dock==='float'){p.width=i.width+dx;p.height=i.height+dy;contain(i.id);}else{state.widths[p.dock]=limit(i.width+(p.dock==='right'?-dx:dx),210,420);p.height=limit(i.height+dy,80,Math.max(120,screen().h-100));widths();}appearance(i.id);requestAnimationFrame(()=>{if(current()&&!$('editor').hidden)sizeStage();});}}
 function end(ev){const i=interaction;if(!i||(ev&&i.pointerId!==ev.pointerId))return;const cancelled=!ev||ev.type==='pointercancel';if(i.type==='move'&&i.changed&&!cancelled&&Number.isFinite(ev.clientX)&&Number.isFinite(ev.clientY))target(i,ev.clientX,ev.clientY);interaction=null;if(i.handle.hasPointerCapture?.(i.pointerId))i.handle.releasePointerCapture(i.pointerId);for(const side of ['left','right'])$(side==='left'?'leftDock':'rightDock').classList.remove('dock-target');if(i.type==='move'&&i.changed&&!cancelled&&['left','right'].includes(i.drop))move(i.id,i.drop,i.before);else save();}
 function reset(){end();state={widths:{left:260,right:260},panels:{}};render();save();toast('Posições e tamanhos dos painéis restaurados.');}
 read();for(const [id,panel]of panels){panel.addEventListener('pointerdown',()=>{if(prefs(id).dock==='float')panel.style.zIndex=++z;});const grip=panel.querySelector('.panel-grip'),resize=panel.querySelector('.panel-resize');resize.innerHTML='<svg viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path d="M3 12h6a3 3 0 0 0 3-3V3"/></svg>';grip.onpointerdown=ev=>start(id,'move',ev);resize.onpointerdown=ev=>start(id,'resize',ev);for(const handle of [grip,resize])handle.onkeydown=ev=>{const delta={ArrowLeft:[-10,0],ArrowRight:[10,0],ArrowUp:[0,-10],ArrowDown:[0,10]}[ev.key];if(!delta)return;ev.preventDefault();ev.stopPropagation();const p=prefs(id);if(handle===grip&&ev.altKey&&['ArrowLeft','ArrowRight'].includes(ev.key)){move(id,ev.key==='ArrowLeft'?'left':'right');return;}if(handle===grip){if(p.dock!=='float')move(id,'float');p.x+=delta[0];p.y+=delta[1];contain(id);}else{if(p.dock==='float'){p.width+=delta[0];p.height=(p.height||panel.getBoundingClientRect().height)+delta[1];contain(id);}else{state.widths[p.dock]=limit(state.widths[p.dock]+(p.dock==='right'?-delta[0]:delta[0]),210,420);p.height=limit((p.height||panel.getBoundingClientRect().height)+delta[1],80,1500);widths();}}appearance(id);save();requestAnimationFrame(()=>{if(current()&&!$('editor').hidden)sizeStage();});};panel.querySelector('.panel-collapse').onclick=()=>{const p=prefs(id);p.collapsed=!p.collapsed;appearance(id);save();};}
 window.addEventListener('pointermove',pointerMove);for(const event of ['pointerup','pointercancel'])window.addEventListener(event,end);window.addEventListener('blur',()=>end());window.addEventListener('resize',()=>{for(const id of panelList)if(prefs(id).dock==='float'){contain(id);appearance(id);}save();});$('resetPanels').onclick=reset;render();
 return{move,reset,state:()=>JSON.parse(JSON.stringify(state)),start,pointerMove,end};
})();
